revolution downcone=cone(c = 5*K,r = 5,h = -5);
draw(surface(downcone),gray(0.99));
draw((-6*I)--6*I, Arrow3(6));
draw((-6*J)--6*J, Arrow3(6));
draw(4.5*K--6*K, Arrow3(6));

label("$x$", 6.5*I);
label("$y$", 6.5*J);
label("$z$", 6.5*K);
